#!/usr/bin/env python3# -*- coding: utf-8 -*-"""4. Timeseries analysis@author: oblig0_289412Jeg har jobbet med datasetet fra 2012 derfor vises andre tallene enn på nettsiden"""from pathlib import Pathimport pandas as pdimport numpy as npimport matplotlib.pyplot as pltimport matplotlib.colors as colorsdef get_path(filepath):    path = Path(filepath)    if not path.exists():        raise FileNotFoundError(f"File not found: {filepath}")    return pathdef read_file(filepath):    path = get_path(filepath)    return pd.read_csv(path, index_col="Date", parse_dates=True)filepath = Path("data") / "FremontBridge.csv"data = read_file(filepath)pd.set_option("display.max_columns", None)print("\n++++++++++++++++++\n")print(data.head())print("\n++++++++++++++++++\n")print(len(data)) def simplify_to_total(df):    df = df.copy()    df.columns = ["Total", "West", "East"]    df = df.drop(["East", "West"], axis="columns")    return dfdata = simplify_to_total(data)print (data.head())def show_data_hour():    data.plot()    plt.ylabel("Hourly Bicycle Count")  # NOTE: that hour data is for every hour    return datashow_data_hour()plt.show    def resample_weekly(df):    weekly = df.resample("W").sum()    return weeklyweekly = resample_weekly(data)print(weekly.index)print("\n++++++++++++++++++\n")print(weekly.index.isocalendar().week)weekly.plot(style=["-"])plt.ylabel("Weekly bicycle count")def resample_hour(df):    by_time = df.groupby(data.index.time).mean()    hourly_ticks = 4 * 60 * 60 * np.arange(6)  # 3600 * 24, every 4 hour    ax = by_time.plot(xticks=hourly_ticks, style=["-"])    return by_time, axby_time, ax = resample_hour(data)plt.showdef plot_by_weekday(df):    by_weekday = df.groupby(data.index.dayofweek).mean()    by_weekday.index = ["Mon", "Tues", "Wed", "Thurs", "Fri", "Sat", "Sun"]    by_weekday.plot(style=["-"])       return by_weekdayby_weekday = plot_by_weekday(data)plt.show# denne må kjøres helt alleine uten de andre som står oversdef plot_weekday_hour_heatmap(df):    Z = df.pivot_table(        "Total", index=df.index.weekday, columns=[df.index.time]    ).values    plt.pcolor(Z, norm=colors.LogNorm(vmin=Z.min(), vmax=Z.max()), cmap="inferno")    plt.colorbar()    plt.show()    return ZZ = plot_weekday_hour_heatmap(data)print(np.isnan(Z).sum())print((Z <= 0).sum())                     